  element.classList.add(...classes);
}

function normalizeAlignment(element: Element): void {
  const alignment =
    (element as HTMLElement).style?.textAlign || element.getAttribute("align") || "";
  const className =
    alignment === "left" || alignment === "start"
      ? "--text-align-start"
      : alignment === "center"
